package net.officefloor.hq.app.claim;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import org.hibernate.annotations.BatchSize;
import org.hibernate.annotations.Generated;

/**
 * A claim by a person on a sheet: an amount (two decimals; below zero only for a correction, which
 * names the number of the settled claim it corrects), a date, a note and a status, once opened its number on the sheet and who opened it, and once settled the due fixed at
 * that moment, and while bound by its person's last statement the figure it had then.
 */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Column(name = "note", nullable = false)
    private String note;

    /** When the claim was added, in the order claims and forward-only rates are saved (see {@link net.officefloor.hq.app.rate.Rate#appliesTo}). */
    @Generated
    @Column(name = "added_seq", insertable = false, updatable = false)
    private Long addedSeq;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /**
     * The claim's number on its sheet, given when it is opened and kept once VOID; none while DRAFT.
     * Sheet-wide ({@code 1}, {@code 2}, ...), or under numbering per period {@code <period name>-<n>}
     * or {@code X-<n>} in no period.
     */
    @Column(name = "claim_number")
    private String number;

    /** The due fixed when the claim was settled; none while not settled or if its grade had no rate. */
    @Column(name = "settled_due")
    private BigDecimal settledDue;

    /** The user who opened the claim; none while DRAFT, or if voided without being opened. */
    @Column(name = "opened_by")
    private String openedBy;

    /** The user who last edited the claim through its form or its row's amount; none while never edited. */
    @Column(name = "edited_by")
    private String editedBy;

    /** Whether the person's last statement bound this claim to the figure it had then. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The figure bound by the last statement; none while unbound or if it had no rate then. */
    @Column(name = "stated_due")
    private BigDecimal statedDue;

    /**
     * The due as shown when the last statement bound the claim, late charge included (and raised to
     * the floor); none while unbound or if it had no rate then.
     */
    @Column(name = "stated_charged")
    private BigDecimal statedCharged;

    /**
     * The date the claim is due by: fixed when it is created, the terms-th business day after its
     * date (skipping Saturdays, Sundays and the sheet's holidays), with the terms of its person's
     * grade in force on its date; later changes to the terms or its date leave it as it is. A holiday
     * added on or before it works it out again (see {@link #getTerms}), unless the claim is SETTLED or VOID.
     */
    @Column(name = "due_by", nullable = false)
    private LocalDate dueBy;

    /** The terms, in business days, the claim's due-by was fixed with. */
    @Column(name = "terms", nullable = false)
    private int terms;

    /** The number of the claim this correction corrects; none for a claim that is not a correction. */
    @Column(name = "corrects")
    private String corrects;

    /** The claim's external reference, unique on its sheet without regard to case; none when not given. */
    @Column(name = "ext_ref")
    private String ref;

    /** The claim's tags: trimmed, lower-cased, without repeats, sorted and comma separated; none when it has none. */
    @Column(name = "tags")
    private String tags;

    /** The number of the claim this claim was split off from; none for a claim not made by a split. */
    @Column(name = "split_from")
    private String splitFrom;

    /** The number of the bulk settle batch that settled the claim (or made it PENDING); none when not settled by one. */
    @Column(name = "batch")
    private Integer batch;

    /** Whether the claim was added while the period its due-by falls in was soft-closed. */
    @Column(name = "late_entry", nullable = false)
    private boolean lateEntry;

    /**
     * The user whose open editor locks the claim for everyone else; none when unlocked. Released
     * when the editor is saved or cancelled, or the sheet's today changes.
     */
    @Column(name = "locked_by")
    private String lockedBy;

    /**
     * The date an OPEN claim is deferred until: while the sheet's today is before it the claim
     * counts in no total, is not overdue and cannot be settled; none when never deferred.
     */
    @Column(name = "deferred_until")
    private LocalDate deferredUntil;

    /** The sheet's today when the claim was last deferred; none when never deferred. */
    @Column(name = "deferred_on")
    private LocalDate deferredOn;

    /** The last sheet-today a reminder was written for the claim; none when never reminded. */
    @Column(name = "reminded_on")
    private LocalDate remindedOn;

    /** Whether the claim has been escalated by a reminder; once ever. */
    @Column(name = "escalated", nullable = false)
    private boolean escalated;

    /** Whether a steward waived the claim's late charge: from then on it bears none; once ever. */
    @Column(name = "waived", nullable = false)
    private boolean waived;

    /** Whether the claim is held: a held claim still counts in every total. */
    @Column(name = "held", nullable = false)
    private boolean held;

    /** The sheet's today when the claim was last held; none when never held. */
    @Column(name = "held_on")
    private LocalDate heldOn;

    /** The sheet's today when the claim last went to REVIEW; none when it never has. */
    @Column(name = "review_on")
    private LocalDate reviewOn;

    /** The reason the claim was voided with; none when voided without one, or not voided. */
    @Column(name = "void_reason")
    private String voidReason;

    /** How many proofs the claim has: raised by one at a time, never while SETTLED or VOID. */
    @Column(name = "proofs", nullable = false)
    private int proofs;

    /** How many of the claim's proofs are photos; the rest are receipts. */
    @Column(name = "photo_proofs", nullable = false)
    private int photoProofs;

    /**
     * The claim's place in the list, newest (highest) first: taken from the store's sequence when
     * the claim is added and again when it is moved to another person.
     */
    @Column(name = "listed", insertable = false, updatable = false)
    private Long listed;

    /** The claim's status log: one entry per status it has had, oldest first. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "claim_log", joinColumns = @JoinColumn(name = "claim_id"))
    @OrderColumn(name = "seq")
    @BatchSize(size = 100)
    private List<ClaimLogEntry> log = new ArrayList<>();

    /** The claim's comments, oldest first. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "claim_comment", joinColumns = @JoinColumn(name = "claim_id"))
    @OrderColumn(name = "seq")
    @BatchSize(size = 100)
    private List<ClaimComment> comments = new ArrayList<>();

    /** The claim's lines, in the order they were added; while it has any, its amount is their total. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "claim_line", joinColumns = @JoinColumn(name = "claim_id"))
    @OrderColumn(name = "seq")
    @BatchSize(size = 100)
    private List<ClaimLine> lines = new ArrayList<>();

    /** A proof that is a receipt, the kind a proof is when none is chosen. */
    public static final String RECEIPT = "receipt";
    public static final String PHOTO = "photo";
    /** The kinds a proof can be. */
    public static final List<String> PROOF_KINDS = List.of(RECEIPT, PHOTO);

    protected Claim() {
    }

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, LocalDate dueBy, int terms,
            String note, String corrects) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.dueBy = dueBy;
        this.terms = terms;
        this.note = note;
        this.corrects = corrects;
    }

    public Long getAddedSeq() {
        return addedSeq;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    /**
     * The claim as it arrives on another sheet under a person transferred there: everything it has
     * (status, dates, note, tags, frozen figures, log and comments) but its number, which the caller
     * gives afresh, its reference, which is not carried, and an editor's lock. A figure a statement
     * bound is kept, as the person's statements go with them.
     */
    public Claim transferredTo(String toSheetId, Long toPersonId) {
        Claim copy = new Claim(toSheetId, toPersonId, amount, date, dueBy, terms, note, corrects);
        copy.status = status;
        copy.settledDue = settledDue;
        copy.stated = stated;
        copy.statedDue = statedDue;
        copy.statedCharged = statedCharged;
        copy.openedBy = openedBy;
        copy.editedBy = editedBy;
        copy.tags = tags;
        copy.splitFrom = splitFrom;
        copy.batch = batch;
        copy.lateEntry = lateEntry;
        copy.deferredUntil = deferredUntil;
        copy.deferredOn = deferredOn;
        copy.remindedOn = remindedOn;
        copy.escalated = escalated;
        copy.reviewOn = reviewOn;
        copy.waived = waived;
        copy.held = held;
        copy.heldOn = heldOn;
        copy.voidReason = voidReason;
        copy.proofs = proofs;
        copy.photoProofs = photoProofs;
        copy.log.addAll(log);
        copy.comments.addAll(comments);
        copy.lines.addAll(lines);
        return copy;
    }

    public Long getPersonId() {
        return personId;
    }

    /** Move the claim to another person. */
    public void setPersonId(Long personId) {
        this.personId = personId;
    }

    public Long getListed() {
        return listed;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public void setDate(LocalDate date) {
        this.date = date;
    }

    public LocalDate getDueBy() {
        return dueBy;
    }

    /** Fix the due-by again, as a holiday added on or before it does. */
    public void setDueBy(LocalDate dueBy) {
        this.dueBy = dueBy;
    }

    public int getTerms() {
        return terms;
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }

    public String getCorrects() {
        return corrects;
    }

    public void setCorrects(String corrects) {
        this.corrects = corrects;
    }

    public String getRef() {
        return ref;
    }

    public void setRef(String ref) {
        this.ref = ref;
    }

    /** The claim's tags, sorted; empty when it has none. */
    public List<String> getTags() {
        return tags == null ? List.of() : List.of(tags.split(","));
    }

    /** Give the claim tags, already trimmed, lower-cased, without repeats and sorted. */
    public void setTags(List<String> tags) {
        this.tags = tags.isEmpty() ? null : String.join(",", tags);
    }

    public Integer getBatch() {
        return batch;
    }

    public void setBatch(Integer batch) {
        this.batch = batch;
    }

    public boolean isLateEntry() {
        return lateEntry;
    }

    public void setLateEntry(boolean lateEntry) {
        this.lateEntry = lateEntry;
    }

    public String getSplitFrom() {
        return splitFrom;
    }

    public void setSplitFrom(String splitFrom) {
        this.splitFrom = splitFrom;
    }

    public String getLockedBy() {
        return lockedBy;
    }

    public void setLockedBy(String lockedBy) {
        this.lockedBy = lockedBy;
    }

    /** Whether another user's open editor locks the claim against the user. */
    public boolean isLockedAgainst(String user) {
        return lockedBy != null && !lockedBy.equals(user);
    }

    /** Whether the claim is a correction: its amount is below zero. Its due has no floor and no late charge. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public void setStatus(ClaimStatus status) {
        this.status = status;
    }

    public String getVoidReason() {
        return voidReason;
    }

    public void setVoidReason(String voidReason) {
        this.voidReason = voidReason;
    }

    public String getNumber() {
        return number;
    }

    public void setNumber(String number) {
        this.number = number;
    }

    public BigDecimal getSettledDue() {
        return settledDue;
    }

    public void setSettledDue(BigDecimal settledDue) {
        this.settledDue = settledDue;
    }

    public String getOpenedBy() {
        return openedBy;
    }

    public void setOpenedBy(String openedBy) {
        this.openedBy = openedBy;
    }

    public String getEditedBy() {
        return editedBy;
    }

    public void setEditedBy(String editedBy) {
        this.editedBy = editedBy;
    }

    public boolean isStated() {
        return stated;
    }

    public BigDecimal getStatedDue() {
        return statedDue;
    }

    public BigDecimal getStatedCharged() {
        return statedCharged;
    }

    /**
     * The due a statement bound, late charge included, while the claim is bound and OPEN or PENDING;
     * none otherwise (its due is worked out from its figure).
     */
    public BigDecimal boundCharged() {
        return stated && status.isOpen() ? statedCharged : null;
    }

    /** Bind the claim to a figure (stated), or unbind it so its figure is live again. */
    public void bind(boolean stated, BigDecimal statedDue) {
        bind(stated, statedDue, null);
    }

    /**
     * Bind the claim to a figure and its due as shown, late charge included (stated), or unbind it
     * so its figure and late charge are live again.
     */
    public void bind(boolean stated, BigDecimal statedDue, BigDecimal statedCharged) {
        this.stated = stated;
        this.statedDue = stated ? statedDue : null;
        this.statedCharged = stated ? statedCharged : null;
    }

    public LocalDate getDeferredUntil() {
        return deferredUntil;
    }

    /** Defer the claim until a date; {@code madeOn} is the sheet's today. */
    public void setDeferredUntil(LocalDate deferredUntil, LocalDate madeOn) {
        this.deferredUntil = deferredUntil;
        this.deferredOn = madeOn;
    }

    /**
     * Whether the claim was deferred at the end of a day, had it the given status then: deferred
     * while the sheet's today was on or before the day, until a date after it.
     */
    public boolean isDeferredAsOf(ClaimStatus status, LocalDate day) {
        return isDeferredOn(status, day) && (deferredOn == null || !deferredOn.isAfter(day));
    }

    /**
     * The due the claim was settled at, as its status log records it at the end of a day (the last
     * line logged on or before it); none when it had none then.
     */
    public BigDecimal settledDueAt(LocalDate day) {
        String due = null;
        for (ClaimLogEntry entry : log) {
            if (!entry.getDate().isAfter(day)) {
                due = entry.getDue();
            }
        }
        return due == null || due.equals("n/a") ? null : new BigDecimal(due);
    }

    /** Whether the claim is open and deferred on the given day: its deferral date not yet reached. */
    public boolean isDeferredOn(LocalDate today) {
        return isDeferredOn(status, today);
    }

    /** Whether the claim would be deferred on the given day, had it the given status. */
    public boolean isDeferredOn(ClaimStatus status, LocalDate today) {
        return status.isOpen() && deferredUntil != null && today != null && today.isBefore(deferredUntil);
    }

    /**
     * The status the claim had at the end of a day, as its status log records it (the last line
     * logged on or before it); empty when it had none yet.
     */
    public Optional<ClaimStatus> statusAt(LocalDate day) {
        ClaimStatus at = null;
        for (ClaimLogEntry entry : log) {
            if (!entry.getDate().isAfter(day)) {
                at = entry.getStatus();
            }
        }
        return Optional.ofNullable(at);
    }

    public int getProofs() {
        return proofs;
    }

    public LocalDate getRemindedOn() {
        return remindedOn;
    }

    public void setRemindedOn(LocalDate remindedOn) {
        this.remindedOn = remindedOn;
    }

    public boolean isEscalated() {
        return escalated;
    }

    public void setEscalated(boolean escalated) {
        this.escalated = escalated;
    }

    public boolean isWaived() {
        return waived;
    }

    public boolean isHeld() {
        return held;
    }

    /** Whether the claim was held at the end of a day: held now, and held while the sheet's today was on or before it. */
    public boolean isHeldAsOf(LocalDate day) {
        return held && (heldOn == null || !heldOn.isAfter(day));
    }

    /** Hold the claim ({@code madeOn} is the sheet's today), or release it. */
    public void setHeld(boolean held, LocalDate madeOn) {
        this.held = held;
        if (held) {
            this.heldOn = madeOn;
        }
    }

    /** Waive the claim's late charge. */
    public void waive() {
        this.waived = true;
    }

    public LocalDate getReviewOn() {
        return reviewOn;
    }

    public void setReviewOn(LocalDate reviewOn) {
        this.reviewOn = reviewOn;
    }

    /** How many of the claim's proofs are of a kind (see {@link #PROOF_KINDS}). */
    public int proofsOf(String kind) {
        return PHOTO.equals(kind) ? photoProofs : RECEIPT.equals(kind) ? proofs - photoProofs : 0;
    }

    /** Raise the claim's proofs count by one, with a proof of a kind (see {@link #PROOF_KINDS}). */
    public void addProof(String kind) {
        proofs++;
        if (PHOTO.equals(kind)) {
            photoProofs++;
        }
    }

    public List<ClaimLogEntry> getLog() {
        return List.copyOf(log);
    }

    /** Add a line to the claim's status log. */
    public void log(ClaimLogEntry entry) {
        log.add(entry);
    }

    /** The claim's comments, oldest first. */
    public List<ClaimComment> getComments() {
        return List.copyOf(comments);
    }

    /** Add a comment to the claim. */
    public void comment(ClaimComment comment) {
        comments.add(comment);
    }

    /** The claim's lines, in the order they were added. */
    public List<ClaimLine> getLines() {
        return List.copyOf(lines);
    }

    /** Add a line to the claim: its amount becomes the total of its lines. */
    public void addLine(ClaimLine line) {
        lines.add(line);
        amount = lines.stream().map(ClaimLine::total).reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}
package net.officefloor.hq.app.claim;

import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Collection;
import net.officefloor.hq.app.sheet.Sheet;

/**
 * How a claim's live figures are rounded to the cent: by the sheet's rounding mode in force on the
 * claim's date when it has one then; else half up when the claim is dated before the sheet's policy
 * date (its today when it has none), half to even when dated on or after it. A correction rounds by
 * the date of the claim it corrects, not its own.
 */
public final class Rounding {

    private Rounding() {
    }

    /** The rounding for a claim dated on the given date. */
    public static RoundingMode mode(Sheet sheet, LocalDate date) {
        String mode = sheet.roundingOn(date);
        if (mode != null) {
            return mode.equals("half-up") ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
        }
        LocalDate policy = sheet.getPolicyDate() != null ? sheet.getPolicyDate() : sheet.getToday();
        return date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /**
     * The date a claim rounds by: its own, or for a correction the date of the claim it corrects,
     * found by number among the sheet's claims (its own when that claim is not among them).
     */
    public static LocalDate dateOf(Claim claim, Collection<Claim> sheetClaims) {
        if (!claim.isCorrection() || claim.getCorrects() == null) {
            return claim.getDate();
        }
        return sheetClaims.stream().filter(c -> claim.getCorrects().equals(c.getNumber())).findFirst()
                .map(Claim::getDate).orElse(claim.getDate());
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.sheet.Sheet;

/**
 * The late charge on an overdue claim (OPEN or PENDING, and past its due-by plus the grace days of its person's grade
 * on its date, see {@link Sheet#lateFrom}, on the sheet's today): for each full 30 days it is overdue, the late
 * percent in force on that boundary date (its due-by plus the grace, plus 30, 60, 90 ... days) of
 * its figure plus the charges of the boundaries before it (the charge compounds), rounded to the cent as the claim rounds (see {@link Rounding}), the charges added up. A correction has none, nor has a claim whose charge was waived. A statement binds the due as shown, charge included (see StatementService); settling a claim fixes it into its due.
 * The floor is applied first: the figure is raised to the floor in force on the claim's date (a correction has no
 * floor), and the charge is worked out on that floored figure (or the floored figure a statement bound); a claim's
 * live due is its floored figure plus its charge.
 */
public final class LateCharge {

    /** The days overdue between boundaries that each add a late charge. */
    private static final int PERIOD_DAYS = 30;

    private LateCharge() {
    }

    /** The figure raised to the floor, with its late charge on that added on top; null when the figure is null. */
    public static BigDecimal withCharge(Sheet sheet, Claim claim, String grade, BigDecimal figure) {
        BigDecimal base = floored(sheet, claim, figure);
        return base == null ? null : base.add(charge(sheet, claim, grade, base));
    }

    /**
     * The figure raised to the floor, with its late charge on that on the sheet's today added on top,
     * the claim open ({@code open}: OPEN or PENDING and not deferred) or not; null when the figure is null.
     */
    public static BigDecimal withCharge(Sheet sheet, Claim claim, String grade, BigDecimal figure, boolean open) {
        BigDecimal base = floored(sheet, claim, figure);
        return base == null ? null : base.add(charge(sheet, claim, grade, base, open));
    }

    /**
     * The figure raised to the floor, with the late charge it would have on the sheet's today were the
     * claim open, whatever its status; null when the figure is null.
     */
    public static BigDecimal withChargeAsOpen(Sheet sheet, Claim claim, String grade, BigDecimal figure) {
        BigDecimal base = floored(sheet, claim, figure);
        return base == null ? null : base.add(charge(sheet, claim, grade, base, true));
    }

    /** A figure raised to the floor in force on the claim's date; a correction's is not; null when it is null. */
    public static BigDecimal floored(Sheet sheet, Claim claim, BigDecimal figure) {
        return figure == null || claim.isCorrection() ? figure : figure.max(sheet.floorOn(claim.getDate()));
    }

    /** The late charge on a claim's figure on the sheet's today; zero when it is not overdue. */
    public static BigDecimal charge(Sheet sheet, Claim claim, String grade, BigDecimal figure) {
        return charge(sheet, claim, grade, figure, claim.getStatus().isOpen() && !claim.isDeferredOn(sheet.getToday()));
    }

    private static BigDecimal charge(Sheet sheet, Claim claim, String grade, BigDecimal figure, boolean open) {
        BigDecimal zero = BigDecimal.ZERO.setScale(2);
        if (figure == null || !open || claim.isCorrection() || claim.isWaived()) {
            return zero;
        }
        LocalDate lateFrom = sheet.lateFrom(claim.getDueBy(), claim.getDate(), grade);
        long periods = ChronoUnit.DAYS.between(lateFrom, sheet.getToday()) / PERIOD_DAYS;
        if (periods <= 0) {
            return zero;
        }
        RoundingMode mode = Rounding.mode(sheet, claim.getDate());
        BigDecimal total = zero;
        for (long k = 1; k <= periods; k++) {
            LocalDate boundary = lateFrom.plusDays(k * PERIOD_DAYS);
            total = total.add(figure.add(total).multiply(sheet.latePctOn(boundary)).divide(BigDecimal.valueOf(100), 2, mode));
        }
        return total;
    }
}
package net.officefloor.hq.app.claim;

/**
 * A claim's status: DRAFT when added; opened (OPEN), then settled (SETTLED). A clerk settling a
 * claim above the clerk limit makes it PENDING instead, until a steward approves it (SETTLED) or
 * rejects it (back to OPEN). A DRAFT, OPEN or PENDING claim can be voided (VOID), and a steward may
 * void a SETTLED one shortly after its settlement (see ClaimService). A VOID claim cannot change status.
 * A DRAFT claim can be deleted (DELETED), and restored to DRAFT on the sheet-today it was deleted
 * (see ClaimService); a DELETED claim counts nowhere and makes no other move. A claim due above the
 * review threshold goes to REVIEW when opened, instead of OPEN, until a steward's review makes it
 * OPEN; a REVIEW claim counts nowhere, and can be voided.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;

    /** Whether a claim in this status may move to the given one. */
    public boolean canBecome(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT || this == PENDING || this == REVIEW;
            case PENDING -> this == OPEN;
            case SETTLED -> this == OPEN || this == PENDING;
            case VOID -> this != VOID && this != DELETED;
            case DELETED -> this == DRAFT;
            case DRAFT -> this == DELETED;
            case REVIEW -> this == DRAFT;
        };
    }

