558	        this.escalated = escalated;
559	    }
560	
561	    public boolean isWaived() {
562	        return waived;
563	    }
564	
565	    public boolean isHeld() {
566	        return held;
567	    }
568	
569	    /** Whether the claim was held at the end of a day: held now, and held while the sheet's today was on or before it. */
570	    public boolean isHeldAsOf(LocalDate day) {
571	        return held && (heldOn == null || !heldOn.isAfter(day));
572	    }
