574	    /** Hold the claim ({@code madeOn} is the sheet's today), or release it. */
575	    public void setHeld(boolean held, LocalDate madeOn) {
576	        this.held = held;
577	        if (held) {
578	            this.heldOn = madeOn;
579	        }
580	    }
581	
582	    /** Waive the claim's late charge. */
583	    public void waive() {
584	        this.waived = true;
