587	    public LocalDate getReviewOn() {
588	        return reviewOn;
589	    }
590	
591	    public void setReviewOn(LocalDate reviewOn) {
592	        this.reviewOn = reviewOn;
593	    }
594	
595	    /** How many of the claim's proofs are of a kind (see {@link #PROOF_KINDS}). */
596	    public int proofsOf(String kind) {
597	        return PHOTO.equals(kind) ? photoProofs : RECEIPT.equals(kind) ? proofs - photoProofs : 0;
598	    }
