640	import java.math.RoundingMode;
641	import java.time.LocalDate;
642	import java.util.Collection;
643	import net.officefloor.hq.app.sheet.Sheet;
644	
645	/**
646	 * How a claim's live figures are rounded to the cent: by the sheet's rounding mode in force on the
647	 * claim's date when it has one then; else half up when the claim is dated before the sheet's policy
648	 * date (its today when it has none), half to even when dated on or after it. A correction rounds by
649	 * the date of the claim it corrects, not its own.
650	 */
651	public final class Rounding {
652	
653	    private Rounding() {
654	    }
655	
656	    /** The rounding for a claim dated on the given date. */
657	    public static RoundingMode mode(Sheet sheet, LocalDate date) {
658	        String mode = sheet.roundingOn(date);
659	        if (mode != null) {
660	            return mode.equals("half-up") ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
661	        }
662	        LocalDate policy = sheet.getPolicyDate() != null ? sheet.getPolicyDate() : sheet.getToday();
663	        return date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
664	    }
665	
666	    /**
667	     * The date a claim rounds by: its own, or for a correction the date of the claim it corrects,
668	     * found by number among the sheet's claims (its own when that claim is not among them).
669	     */
670	    public static LocalDate dateOf(Claim claim, Collection<Claim> sheetClaims) {
671	        if (!claim.isCorrection() || claim.getCorrects() == null) {
672	            return claim.getDate();
673	        }
674	        return sheetClaims.stream().filter(c -> claim.getCorrects().equals(c.getNumber())).findFirst()
675	                .map(Claim::getDate).orElse(claim.getDate());
676	    }
677	}
