679	
680	import java.math.BigDecimal;
681	import java.math.RoundingMode;
682	import java.time.LocalDate;
683	import java.time.temporal.ChronoUnit;
684	import net.officefloor.hq.app.sheet.Sheet;
685	
686	/**
687	 * The late charge on an overdue claim (OPEN or PENDING, and past its due-by plus the grace days of its person's grade
688	 * on its date, see {@link Sheet#lateFrom}, on the sheet's today): for each full 30 days it is overdue, the late
689	 * percent in force on that boundary date (its due-by plus the grace, plus 30, 60, 90 ... days) of
690	 * its figure plus the charges of the boundaries before it (the charge compounds), rounded to the cent as the claim rounds (see {@link Rounding}), the charges added up. A correction has none, nor has a claim whose charge was waived. A statement binds the due as shown, charge included (see StatementService); settling a claim fixes it into its due.
691	 * The floor is applied first: the figure is raised to the floor in force on the claim's date (a correction has no
692	 * floor), and the charge is worked out on that floored figure (or the floored figure a statement bound); a claim's
693	 * live due is its floored figure plus its charge.
694	 */
695	public final class LateCharge {
696	
697	    /** The days overdue between boundaries that each add a late charge. */
698	    private static final int PERIOD_DAYS = 30;
699	
700	    private LateCharge() {
701	    }
702	
703	    /** The figure raised to the floor, with its late charge on that added on top; null when the figure is null. */
704	    public static BigDecimal withCharge(Sheet sheet, Claim claim, String grade, BigDecimal figure) {
705	        BigDecimal base = floored(sheet, claim, figure);
706	        return base == null ? null : base.add(charge(sheet, claim, grade, base));
707	    }
708	
709	    /**
710	     * The figure raised to the floor, with its late charge on that on the sheet's today added on top,
711	     * the claim open ({@code open}: OPEN or PENDING and not deferred) or not; null when the figure is null.
712	     */
713	    public static BigDecimal withCharge(Sheet sheet, Claim claim, String grade, BigDecimal figure, boolean open) {
714	        BigDecimal base = floored(sheet, claim, figure);
715	        return base == null ? null : base.add(charge(sheet, claim, grade, base, open));
716	    }
717	
718	    /**
719	     * The figure raised to the floor, with the late charge it would have on the sheet's today were the
720	     * claim open, whatever its status; null when the figure is null.
721	     */
722	    public static BigDecimal withChargeAsOpen(Sheet sheet, Claim claim, String grade, BigDecimal figure) {
723	        BigDecimal base = floored(sheet, claim, figure);
724	        return base == null ? null : base.add(charge(sheet, claim, grade, base, true));
725	    }
726	
727	    /** A figure raised to the floor in force on the claim's date; a correction's is not; null when it is null. */
728	    public static BigDecimal floored(Sheet sheet, Claim claim, BigDecimal figure) {
729	        return figure == null || claim.isCorrection() ? figure : figure.max(sheet.floorOn(claim.getDate()));
730	    }
731	
732	    /** The late charge on a claim's figure on the sheet's today; zero when it is not overdue. */
733	    public static BigDecimal charge(Sheet sheet, Claim claim, String grade, BigDecimal figure) {
734	        return charge(sheet, claim, grade, figure, claim.getStatus().isOpen() && !claim.isDeferredOn(sheet.getToday()));
735	    }
736	
737	    private static BigDecimal charge(Sheet sheet, Claim claim, String grade, BigDecimal figure, boolean open) {
738	        BigDecimal zero = BigDecimal.ZERO.setScale(2);
739	        if (figure == null || !open || claim.isCorrection() || claim.isWaived()) {
740	            return zero;
741	        }
742	        LocalDate lateFrom = sheet.lateFrom(claim.getDueBy(), claim.getDate(), grade);
743	        long periods = ChronoUnit.DAYS.between(lateFrom, sheet.getToday()) / PERIOD_DAYS;
744	        if (periods <= 0) {
745	            return zero;
746	        }
747	        RoundingMode mode = Rounding.mode(sheet, claim.getDate());
748	        BigDecimal total = zero;
749	        for (long k = 1; k <= periods; k++) {
750	            LocalDate boundary = lateFrom.plusDays(k * PERIOD_DAYS);
751	            total = total.add(figure.add(total).multiply(sheet.latePctOn(boundary)).divide(BigDecimal.valueOf(100), 2, mode));
752	        }
753	        return total;
754	    }
755	}
756	package net.officefloor.hq.app.claim;
757	
758	/**
759	 * A claim's status: DRAFT when added; opened (OPEN), then settled (SETTLED). A clerk settling a
760	 * claim above the clerk limit makes it PENDING instead, until a steward approves it (SETTLED) or
761	 * rejects it (back to OPEN). A DRAFT, OPEN or PENDING claim can be voided (VOID), and a steward may
762	 * void a SETTLED one shortly after its settlement (see ClaimService). A VOID claim cannot change status.
763	 * A DRAFT claim can be deleted (DELETED), and restored to DRAFT on the sheet-today it was deleted
764	 * (see ClaimService); a DELETED claim counts nowhere and makes no other move. A claim due above the
765	 * review threshold goes to REVIEW when opened, instead of OPEN, until a steward's review makes it
766	 * OPEN; a REVIEW claim counts nowhere, and can be voided.
767	 */
768	public enum ClaimStatus {
769	    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;
770	
771	    /** Whether a claim in this status may move to the given one. */
772	    public boolean canBecome(ClaimStatus next) {
773	        return switch (next) {
774	            case OPEN -> this == DRAFT || this == PENDING || this == REVIEW;
775	            case PENDING -> this == OPEN;
776	            case SETTLED -> this == OPEN || this == PENDING;
777	            case VOID -> this != VOID && this != DELETED;
778	            case DELETED -> this == DRAFT;
779	            case DRAFT -> this == DELETED;
780	            case REVIEW -> this == DRAFT;
781	        };
782	    }
783	
784	    /** Whether a claim in this status counts toward the totals: OPEN, PENDING and SETTLED do. */
785	    public boolean counts() {
786	        return this == OPEN || this == PENDING || this == SETTLED;
787	    }
788	
789	    /** Whether a claim in this status is open: OPEN or PENDING (it goes overdue). */
790	    public boolean isOpen() {
791	        return this == OPEN || this == PENDING;
792	    }
793	}
