799	import net.officefloor.hq.app.person.Person;
800	import net.officefloor.hq.app.person.PersonRepository;
801	import net.officefloor.hq.app.sheet.AsOfFilter;
802	import net.officefloor.hq.app.sheet.SheetHistory;
803	import net.officefloor.hq.app.sheet.SheetService;
804	import org.springframework.http.HttpStatus;
805	import org.springframework.stereotype.Service;
806	import org.springframework.transaction.PlatformTransactionManager;
807	import org.springframework.transaction.support.TransactionTemplate;
808	import org.springframework.web.context.request.RequestAttributes;
809	import org.springframework.web.context.request.RequestContextHolder;
810	import org.springframework.web.server.ResponseStatusException;
811	
812	/**
813	 * A claim's due as it stood at the end of a day: worked out as the as-of view works it out (see
814	 * {@link AsOfFilter}), from the sheet restored as it stood then, its today the date, in a transaction
815	 * that is then rolled back.
816	 */
817	@Service
818	public class ClaimAsOf {
819	
820	    private final ClaimRepository claims;
821	    private final PersonRepository people;
822	    private final ClaimService service;
823	    private final SheetService sheets;
824	    private final SheetHistory history;
825	    private final EntityManager entities;
826	    private final TransactionTemplate readOnly;
827	    private final TransactionTemplate rolledBack;
828	
829	    public ClaimAsOf(ClaimRepository claims, PersonRepository people, ClaimService service, SheetService sheets,
830	            SheetHistory history, EntityManager entities, PlatformTransactionManager transactions) {
831	        this.claims = claims;
832	        this.people = people;
833	        this.service = service;
834	        this.sheets = sheets;
835	        this.history = history;
836	        this.entities = entities;
837	        this.readOnly = new TransactionTemplate(transactions);
838	        this.readOnly.setReadOnly(true);
839	        this.rolledBack = new TransactionTemplate(transactions);
840	    }
841	
842	    /**
843	     * The claim's due at the end of {@code day} (null when it had none). Refused (409) for a day after
844	     * the sheet's today, and for a claim that was not on the sheet then.
845	     */
846	    public BigDecimal due(String sheetId, long id, LocalDate day) {
847	        LocalDate today = readOnly.execute(status -> sheets.today(sheetId));
848	        if (day.isAfter(today)) {
849	            throw new ResponseStatusException(HttpStatus.CONFLICT,
850	                    "A claim cannot be settled as of a date after the sheet's today.");
851	        }
852	        RequestAttributes request = RequestContextHolder.getRequestAttributes();
853	        Object was = request == null ? null : request.getAttribute(AsOfFilter.AS_OF, RequestAttributes.SCOPE_REQUEST);
854	        if (request != null) {
855	            // the sheet's ancestors are read as of the day too, as the as-of view reads them
856	            request.setAttribute(AsOfFilter.AS_OF, day, RequestAttributes.SCOPE_REQUEST);
857	        }
858	        try {
859	            return rolledBack.execute(status -> {
860	                status.setRollbackOnly();
861	                history.restore(sheetId, day);
862	                // the rows were put back behind the persistence context's back: read them afresh
863	                entities.clear();
864	                Claim claim = claims.findByIdAndSheetId(id, sheetId)
865	                        .filter(c -> c.getStatus() != ClaimStatus.DELETED)
866	                        .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
867	                                "This claim was not on the sheet on " + day + "."));
868	                Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
869	                        .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
870	                                "This claim was not on the sheet on " + day + "."));
871	                BigDecimal due = service.charged(sheetId, person, claim);
872	                entities.clear();
873	                return due;
874	            });
875	        } finally {
876	            if (request != null) {
877	                if (was == null) {
878	                    request.removeAttribute(AsOfFilter.AS_OF, RequestAttributes.SCOPE_REQUEST);
879	                } else {
880	                    request.setAttribute(AsOfFilter.AS_OF, was, RequestAttributes.SCOPE_REQUEST);
881	                }
882	            }
883	        }
884	    }
885	}
