117	    /**
118	     * A claim's figure under any late charge: the due fixed when settled, else the one bound by a
119	     * statement, else the live due; null when it has none.
120	     */
121	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
122	        if (isFrozen(claim)) {
123	            return claim.getSettledDue();
124	        }
125	        return claim.isStated() ? claim.getStatedDue()
126	                : due(sheetId, person, claim);
127	    }
128	
129	    /** Whether the claim's figure is the due fixed when settled: SETTLED, or VOID once settled. */
130	    private static boolean isFrozen(Claim claim) {
131	        return claim.getStatus() == ClaimStatus.SETTLED
132	                || (claim.getStatus() == ClaimStatus.VOID && claim.getSettledDue() != null);
133	    }
134	
135	    /**
136	     * A claim's due on the sheet's today: the due fixed when settled, else the due as shown that a
137	     * statement bound (late charge included), else its figure raised to the floor with its late
138	     * charge on that added on top (see {@link LateCharge}); null when it has none.
139	     */
140	    public BigDecimal charged(String sheetId, Person person, Claim claim) {
141	        if (isFrozen(claim)) {
142	            return claim.getSettledDue();
143	        }
144	        if (claim.boundCharged() != null) {
145	            return claim.boundCharged();
146	        }
147	        return LateCharge.withCharge(sheets.sheet(sheetId), claim, person.gradeOn(claim.getDate()), figure(sheetId, person, claim));
148	    }
