175	    @Transactional
176	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
177	            String corrects, String ref, List<String> tags) {
178	        roles.refuseViewer(sheetId, user);
179	        Person person = person(sheetId, personId);
180	        LocalDate dated = dateOrToday(sheetId, date);
181	        int terms = terms(sheetId, person);
182	        LocalDate dueBy = dueBy(sheetId, dated, terms);
183	        periods.refuseIfClosed(sheetId, dueBy);
184	        refuseIfRetired(person, dated);
185	        String corrected = corrected(sheetId, personId, null, amount, corrects);
186	        refuseIfRefUsed(sheetId, ref, null);
187	        RollupService.Snapshot before = rollup.snapshot(sheetId);
188	        Claim claim = new Claim(sheetId, personId, amount, dated, dueBy, terms, note, corrected);
189	        claim.setRef(ref);
190	        claim.setTags(tags);
191	        claim.setLateEntry(periods.isSoftClosed(sheetId, dueBy));
192	        // logged once saved: its due needs the point it was added at (see Rate#appliesTo)
193	        Claim added = claims.saveAndFlush(claim);
194	        logStatus(sheetId, user, person, added);
195	        added = claims.saveAndFlush(added);
196	        audit.recordOnCommit(record("CLAIM_ADDED", sheetId, user, person, added)
197	                + (added.getRef() != null ? " ref=" + added.getRef() : "")
198	                + (added.getTags().isEmpty() ? "" : " tags=" + String.join(",", added.getTags())));
199	        useTags(sheetId, added);
200	        if (added.isLateEntry()) {
201	            audit.recordOnCommit(record("LATE_ENTRY", sheetId, user, person, added));
202	        }
203	        rollup.recordChanges(sheetId, user, before);
204	        return added;
205	    }
