207	    /**
208	     * Whether the claim form would take a claim of the person dated so, as far as its date decides:
209	     * its due-by is inside no closed period and the person's retirements do not refuse the date.
210	     */
211	    @Transactional(readOnly = true)
212	    public boolean takesDate(String sheetId, long personId, LocalDate date) {
213	        Person person = person(sheetId, personId);
214	        LocalDate dueBy = dueBy(sheetId, date, terms(sheetId, person));
215	        return !periods.isClosed(sheetId, dueBy) && !person.refusesClaimOn(date);
216	    }
