218	    @Transactional
219	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
220	            String corrects, String ref, List<String> tags) {
221	        roles.refuseViewer(sheetId, user);
222	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
223	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
224	        refuseIfNotEditable(sheetId, user, claim);
225	        LocalDate dated = dateOrToday(sheetId, date);
226	        periods.refuseIfClosed(sheetId, claim.getDueBy());
227	        refuseIfRetired(person(sheetId, claim.getPersonId()), dated);
228	        if (!claim.getLines().isEmpty() && amount.compareTo(claim.getAmount()) != 0) {
229	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
230	                    "A claim with lines takes its amount from them.");
231	        }
232	        String corrected = corrected(sheetId, claim.getPersonId(), claim.getId(), amount, corrects);
233	        refuseIfRefUsed(sheetId, ref, claim.getId());
234	        RollupService.Snapshot before = rollup.snapshot(sheetId);
235	        claim.setAmount(amount);
236	        claim.setRef(ref);
237	        claim.setTags(tags);
238	        claim.setDate(dated);
239	        claim.setNote(note);
240	        claim.setCorrects(corrected);
241	        claim.setLockedBy(null);
242	        claim.setEditedBy(user);
243	        Claim saved = claims.saveAndFlush(claim);
244	        useTags(sheetId, saved);
245	        audit.recordOnCommit(record("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved));
246	        rollup.recordChanges(sheetId, user, before);
247	        return saved;
248	    }
