250	    /**
251	     * Change a DRAFT claim's amount in its row, keeping its date, note and correction: refused
252	     * exactly as the claim form's save is, and recorded as CLAIM_EDITED as it is. An editor the
253	     * user has open on the claim stays open.
254	     */
255	    @Transactional
256	    public Claim updateAmount(String sheetId, String user, long id, BigDecimal amount) {
257	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
258	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
259	        String lockedBy = claim.getLockedBy();
260	        Claim saved = update(sheetId, user, id, amount, claim.getDate(), claim.getNote(), claim.getCorrects(),
261	                claim.getRef(), claim.getTags());
262	        saved.setLockedBy(lockedBy);
263	        return claims.saveAndFlush(saved);
264	    }
