266	    /**
267	     * Open a claim's editor: the claim is locked for every other user until the editor is saved or
268	     * cancelled, or the sheet's today changes. Refused (403) for a viewer, (409) for a claim that is
269	     * not DRAFT or is locked by another user, and (423) when dated inside a closed period; a refused
270	     * claim takes no lock. Any other claim of the same person the user had locked is released.
271	     */
272	    @Transactional
273	    public Claim lock(String sheetId, String user, long id) {
274	        roles.refuseViewer(sheetId, user);
275	        // hold the sheet so two users cannot both take the lock
276	        sheets.lock(sheetId);
277	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
278	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
279	        refuseIfNotEditable(sheetId, user, claim);
280	        periods.refuseIfClosed(sheetId, claim.getDueBy());
281	        for (Claim other : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId())) {
282	            if (other.getId() != id && user.equals(other.getLockedBy())) {
283	                other.setLockedBy(null);
284	                claims.save(other);
285	            }
286	        }
287	        claim.setLockedBy(user);
288	        return claims.saveAndFlush(claim);
289	    }
290	
291	    /** Cancel a claim's editor: the user's lock on the claim is released; another user's lock stays. */
292	    @Transactional
293	    public Claim unlock(String sheetId, String user, long id) {
294	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
295	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
296	        if (user.equals(claim.getLockedBy())) {
297	            claim.setLockedBy(null);
298	            claim = claims.saveAndFlush(claim);
299	        }
300	        return claim;
301	    }
