303	    /** Refuse (409) editing a claim that is not DRAFT, or that another user's open editor locks. */
304	    private static void refuseIfNotEditable(String sheetId, String user, Claim claim) {
305	        if (claim.getStatus() != ClaimStatus.DRAFT) {
306	            throw new ResponseStatusException(HttpStatus.CONFLICT,
307	                    "A " + claim.getStatus() + " claim cannot be edited.");
308	        }
309	        if (claim.isLockedAgainst(user)) {
310	            throw new ResponseStatusException(HttpStatus.CONFLICT,
311	                    "This claim is being edited by " + claim.getLockedBy() + ".");
312	        }
313	    }
