364	
365	    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus next, String reason,
366	            boolean review, String voidReason, boolean judged) {
367	        return changeStatus(sheetId, user, id, next, reason, review, voidReason, judged, null, null);
368	    }
369	
370	    /**
371	     * Move a claim to a new status; {@code review} for a steward's approval or rejection of a PENDING
372	     * claim, {@code judged} when the four-eyes and proof rules were already judged on the claim it was
373	     * split off (see {@link #partSettle}); {@code on} when settling as of that date, at the due
374	     * {@code asOfDue} it had then.
375	     */
376	    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus next, String reason,
377	            boolean review, String voidReason, boolean judged, LocalDate on, BigDecimal asOfDue) {
378	        roles.refuseViewer(sheetId, user);
379	        if (!review) {
380	            roles.refuseUnlessPermitted(sheetId, user, switch (next) {
381	                case OPEN -> "open";
382	                case SETTLED -> "settle";
383	                case VOID -> "void";
384	                default -> throw new IllegalStateException();
385	            });
386	        }
387	        // lock the sheet's numbering before reading the claim, so a claim is opened (and numbered) once
388	        if (next == ClaimStatus.OPEN) {
389	            sheets.lock(sheetId);
390	        }
391	        RollupService.Snapshot before = rollup.snapshot(sheetId);
392	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
393	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
394	        ClaimStatus was = claim.getStatus();
395	        // only a steward's review moves a PENDING claim on, other than voiding it
396	        // only a steward's review (see #review) moves a REVIEW claim on, other than voiding it
397	        if (!was.canBecome(next) || (next != ClaimStatus.VOID && review != (was == ClaimStatus.PENDING))
398	                || (next != ClaimStatus.VOID && was == ClaimStatus.REVIEW)) {
399	            throw new ResponseStatusException(HttpStatus.CONFLICT,
400	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
401	        }
402	        periods.refuseIfClosed(sheetId, claim.getDueBy());
403	        boolean reversing = was == ClaimStatus.SETTLED;
404	        if (reversing) {
405	            refuseVoidSettled(sheetId, user, claim);
406	        }
407	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
408	            throw new ResponseStatusException(HttpStatus.CONFLICT,
409	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then.");
410	        }
411	        if (next == ClaimStatus.SETTLED && !judged && user.equals(claim.getOpenedBy())) {
412	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
413	                    "The user who opened a claim cannot " + (review ? "approve" : "settle") + " it.");
414	        }
415	        if (next == ClaimStatus.SETTLED && !judged && user.equals(claim.getEditedBy())) {
416	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
417	                    "The user who last edited a claim cannot " + (review ? "approve" : "settle") + " it.");
418	        }
419	        Person person = person(sheetId, claim.getPersonId());
420	        if (review && !isSteward(sheetId, user) && !user.equals(person.getApprover())) {
421	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
422	                    "Only a steward or the person's approver can approve or reject a PENDING claim.");
423	        }
424	        String voidedWith = next == ClaimStatus.VOID ? voidReasons.refuseUnlessListed(sheetId, voidReason) : null;
425	        if (next == ClaimStatus.OPEN && !review && flaggedAgainst(sheetId, user, person)) {
426	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
427	                    "This person is flagged: only a steward can open their claims.");
428	        }
429	        if (next == ClaimStatus.OPEN && !review && atPeriodCap(sheetId, claim)) {
430	            throw new ResponseStatusException(HttpStatus.CONFLICT,
431	                    "This person already has as many open claims in that period as it allows.");
432	        }
433	        if (next == ClaimStatus.OPEN && !review && needsNote(sheetId, person, claim)) {
434	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
435	                    "A claim due above the note threshold cannot be opened with an empty note.");
436	        }
437	        if (next == ClaimStatus.OPEN && !review && needsReview(sheetId, person, claim)) {
438	            next = ClaimStatus.REVIEW;
439	        }
440	        // settling fixes the figure with its late charge as it stands on the sheet's today (a
441	        // PENDING claim keeps any figure a statement bound)
442	        BigDecimal settling = next != ClaimStatus.SETTLED ? null
443	                : on != null ? asOfDue : charged(sheetId, person, claim);
444	        if (next == ClaimStatus.SETTLED && !judged && needsProof(sheetId, person, claim, settling)) {
445	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
446	                    "A claim due above the proof threshold cannot be " + (review ? "approved" : "settled")
447	                            + " without a proof of each kind the sheet needs.");
448	        }
449	        if (next == ClaimStatus.SETTLED && !review && aboveClerkLimit(sheetId, user, person, settling)) {
450	            next = ClaimStatus.PENDING;
451	            settling = null;
452	        }
453	        claim.setStatus(next);
454	        if (next == ClaimStatus.OPEN && !review) {
455	            claim.setNumber(sheets.nextClaimNumber(sheetId, claim.getDueBy()));
456	            claim.setOpenedBy(user);
457	        } else if (next == ClaimStatus.REVIEW) {
458	            claim.setOpenedBy(user);
459	            claim.setReviewOn(sheets.today(sheetId));
460	        } else if (next == ClaimStatus.SETTLED) {
461	            claim.setSettledDue(settling);
462	        } else if (next == ClaimStatus.VOID) {
463	            claim.setVoidReason(voidedWith);
464	        }
465	        logStatus(sheetId, user, person, claim);
466	        Claim saved = claims.saveAndFlush(claim);
467	        String event = switch (next) {
468	            case OPEN -> review ? "CLAIM_REJECTED" : "CLAIM_OPENED";
469	            case PENDING -> "CLAIM_PENDING";
470	            case SETTLED -> review ? "CLAIM_APPROVED" : "CLAIM_SETTLED";
471	            case VOID -> "CLAIM_VOIDED";
472	            case REVIEW -> "CLAIM_REVIEW";
473	            case DRAFT, DELETED -> throw new IllegalStateException();
474	        };
475	        audit.recordOnCommit(record(event, sheetId, user, person, saved)
476	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
477	                + (next == ClaimStatus.SETTLED ? " due=" + dueText(saved.getSettledDue()) : "")
478	                + (reason != null ? " reason=" + reason : "")
479	                + (reversing ? " reversed=" + dueText(saved.getSettledDue()) : "")
480	                + (voidedWith != null ? " reason=" + voidedWith : "")
481	                + (next == ClaimStatus.SETTLED && on != null ? " on=" + on : ""));
482	        if (next == ClaimStatus.SETTLED) {
483	            notifyWatchers(sheetId, user, person, saved);
484	        }
485	        rollup.recordChanges(sheetId, user, before);
486	        return saved;
487	    }
488	
489	    /**
490	     * A steward's review of a REVIEW claim: it becomes OPEN and takes the next number, keeping who
491	     * opened it; CLAIM_REVIEWED is written, then CLAIM_OPENED with its number. Refused (403) for
492	     * anyone but a steward, (409) for a claim that is not REVIEW and (423) when due inside a closed
493	     * period.
494	     */
495	    @Transactional
496	    public Claim review(String sheetId, String user, long id) {
497	        roles.refuseViewer(sheetId, user);
498	        // lock the sheet's numbering before reading the claim, as opening one does
499	        sheets.lock(sheetId);
500	        RollupService.Snapshot before = rollup.snapshot(sheetId);
501	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
502	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
503	        if (claim.getStatus() != ClaimStatus.REVIEW) {
504	            throw new ResponseStatusException(HttpStatus.CONFLICT,
505	                    "A " + claim.getStatus() + " claim cannot be reviewed.");
506	        }
507	        if (!isSteward(sheetId, user)) {
508	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can review a claim.");
509	        }
510	        periods.refuseIfClosed(sheetId, claim.getDueBy());
