714	     * Remind an OPEN or PENDING claim: write REMIND and mark it reminded on the sheet's today. With an
715	     * escalation gap set, a claim never escalated whose previous reminder was at least that many days
716	     * before the sheet's today is escalated too: ESCALATE is written after REMIND.
717	     * Refused (409) for a claim in any other status or already reminded on the sheet's today.
718	     */
719	    @Transactional
720	    public Claim remind(String sheetId, String user, long id) {
721	        roles.refuseViewer(sheetId, user);
722	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
723	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
724	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
725	            throw new ResponseStatusException(HttpStatus.CONFLICT,
726	                    "A " + claim.getStatus() + " claim cannot be reminded.");
727	        }
728	        LocalDate today = sheets.today(sheetId);
729	        if (today.equals(claim.getRemindedOn())) {
730	            throw new ResponseStatusException(HttpStatus.CONFLICT, "This claim was already reminded today.");
