885	    private Claim reassign(String sheetId, String user, long id, long toPersonId, boolean allowSamePerson) {
886	        roles.refuseUnlessPermitted(sheetId, user, "reassign");
887	        // lock the sheet's numbering before reading the claim, as opening one does
888	        sheets.lock(sheetId);
889	        RollupService.Snapshot before = rollup.snapshot(sheetId);
890	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
891	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
892	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
893	                || claim.getStatus() == ClaimStatus.DELETED) {
894	            throw new ResponseStatusException(HttpStatus.CONFLICT,
895	                    "A " + claim.getStatus() + " claim cannot be moved.");
896	        }
897	        Person from = person(sheetId, claim.getPersonId());
898	        Person to = person(sheetId, toPersonId);
899	        if (!allowSamePerson && from.getId().equals(to.getId())) {
900	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is already on that person.");
901	        }
902	        if (claim.isCorrection() && claim.getStatus() != ClaimStatus.DRAFT) {
903	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A correction cannot be moved.");
904	        }
905	        periods.refuseIfClosed(sheetId, claim.getDueBy());
906	        refuseIfRetired(to, claim.getDate());
907	        // a numbered claim moved (in place too) takes the next number; its old one is not reused
908	        if (claim.getNumber() != null) {
909	            claim.setNumber(sheets.nextClaimNumber(sheetId, claim.getDueBy()));
910	        }
911	        claim.setPersonId(to.getId());
912	        claim.bind(false, null);
913	        claims.saveAndFlush(claim);
914	        claims.listFirst(claim.getId());
915	        Claim saved = claims.findByIdAndSheetId(id, sheetId).orElseThrow();
916	        audit.recordOnCommit(record("CLAIM_REASSIGNED", sheetId, user, to, saved)
917	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
918	                + " from=" + from.getName() + " to=" + to.getName());
919	        rollup.recordChanges(sheetId, user, before);
920	        return saved;
921	    }
