1069	    /**
1070	     * Settle the given claims together, all or nothing: in list order (the order people were added,
1071	     * newest claim first within a person), each by exactly the rules of settling one claim. A claim
1072	     * a clerk's settle makes PENDING counts as settled. When any selected claim cannot be settled
1073	     * (or is not on the sheet), none is: every one counts as refused and nothing is written. Else the
1074	     * settle is a batch: it takes the sheet's next batch number, each claim is marked with it, and
1075	     * after the claims' own records one BATCH_SETTLED record gives the batch, its count and the
1076	     * frozen dues of those SETTLED added up, n/a skipped.
1077	     */
1078	    @Transactional
1079	    public BulkSettled bulkSettle(String sheetId, String user, Collection<Long> ids) {
1080	        List<Claim> selected = inListOrder(sheetId, ids);
1081	        int requested = (int) ids.stream().distinct().count();
1082	        List<Claim> settled = new ArrayList<>();
1083	        boolean refusedAny = selected.size() < requested;
1084	        for (Claim claim : selected) {
1085	            if (refusedAny) {
1086	                break;
1087	            }
1088	            try {
1089	                settled.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED));
1090	            } catch (ResponseStatusException refusedOne) {
1091	                refusedAny = true;
1092	            }
1093	        }
1094	        if (refusedAny || settled.isEmpty()) {
1095	            // undo the claims already settled, and the records waiting for the commit with them
1096	            TransactionAspectSupport.currentTransactionStatus().setRollbackOnly();
1097	            return new BulkSettled(0, requested, List.of(), sheets.sheet(sheetId).getLastBatch());
1098	        }
1099	        int batch = sheets.nextBatch(sheetId);
1100	        List<Claim> batched = new ArrayList<>();
1101	        BigDecimal total = BigDecimal.ZERO;
1102	        for (Claim claim : settled) {
1103	            claim.setBatch(batch);
1104	            batched.add(claims.saveAndFlush(claim));
1105	            if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) { // n/a skipped
1106	                total = total.add(claim.getSettledDue());
1107	            }
1108	        }
1109	        audit.recordOnCommit("BATCH_SETTLED sheet=" + sheetId + " by=" + user + " batch=" + batch
1110	                + " count=" + batched.size() + " total=" + dueText(total));
1111	        return new BulkSettled(batched.size(), 0, batched, batch);
1112	    }
