1199	                .flatMap(id -> claims.findByIdAndSheetId(id, sheetId).stream())
1200	                .sorted(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
