1223	    /**
1224	     * Preview a candidate rate for a grade, as if it applied to that grade on every date: of the
1225	     * OPEN and PENDING claims whose person has the grade on the claim's date, how many would show a
1226	     * different due and the sum of the differences (new due minus current due). A claim bound by a
1227	     * statement keeps its figure; a claim with no due counts as 0.00. Nothing is saved.
1228	     */
1229	    @Transactional(readOnly = true)
1230	    public RatePreview previewRate(String sheetId, String grade, BigDecimal pct) {
1231	        Sheet sheet = sheets.sheet(sheetId);
1232	        Map<Long, Person> byId = new HashMap<>();
1233	        for (Person p : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
1234	            byId.put(p.getId(), p);
1235	        }
1236	        int count = 0;
1237	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
1238	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
1239	            Person person = byId.get(claim.getPersonId());
1240	            if (person == null || !claim.getStatus().isOpen() || !grade.equals(person.gradeOn(claim.getDate()))) {
1241	                continue;
1242	            }
1243	            if (claim.isStated()) {
1244	                continue;
1245	            }
1246	            BigDecimal current = charged(sheetId, person, claim);
1247	            RoundingMode rounding = Rounding.mode(sheet, roundingDate(sheetId, claim));
1248	            BigDecimal figure = claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding);
1249	            BigDecimal next = LateCharge.withCharge(sheet, claim, grade, figure);
1250	            BigDecimal was = current == null ? BigDecimal.ZERO : current;
1251	            if (current == null || was.compareTo(next) != 0) {
1252	                count++;
1253	                diff = diff.add(next.subtract(was));
1254	            }
1255	        }
1256	        return new RatePreview(count, diff.setScale(2, RoundingMode.UNNECESSARY));
1257	    }
