1321	    /**
1322	     * The number a claim corrects: none unless its amount is negative, when it must name the number
1323	     * of a SETTLED claim of the same person, else it is refused (400). It may not exceed what remains
1324	     * of that claim: its amount less the corrections already made against it (VOID and DELETED ones,
1325	     * and the claim being edited, left out), else it is refused (422).
1326	     */
1327	    private String corrected(String sheetId, long personId, Long editedId, BigDecimal amount, String corrects) {
1328	        if (amount.signum() >= 0) {
1329	            return null;
1330	        }
1331	        List<Claim> personClaims = corrects == null ? List.of()
1332	                : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
1333	        Claim target = personClaims.stream()
1334	                .filter(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED)
1335	                .findFirst().orElse(null);
1336	        if (target == null) {
1337	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
1338	                    "A negative amount must correct a SETTLED claim of the same person, by its number.");
1339	        }
1340	        BigDecimal remaining = personClaims.stream()
1341	                .filter(c -> corrects.equals(c.getCorrects()) && c.isCorrection()
1342	                        && c.getStatus() != ClaimStatus.VOID && c.getStatus() != ClaimStatus.DELETED
1343	                        && !c.getId().equals(editedId))
1344	                .map(Claim::getAmount).reduce(target.getAmount(), BigDecimal::add);
1345	        if (amount.negate().compareTo(remaining) > 0) {
1346	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
1347	                    "A correction may not exceed what remains of the claim it corrects (" + remaining + ").");
1348	        }
1349	        return corrects;
1350	    }
